/// Remove every comment, keeping a block comment's NEWLINES so line numbers downstream still line up.
///
/// Same string/template handling as [`crate::record_source::blank_comments`], and for the same reason. Differs from it in what
/// it leaves behind: this shortens the text, so it is for reading, while `blank_comments` preserves every
/// offset and is for scanning.
pub fn strip_comments(src: &str) -> String {
    let c: Vec<char> = src.chars().collect();
    let n = c.len();
    let mut out = String::with_capacity(src.len());
    let mut i = 0usize;
    while i < n {
        let ch = c[i];
        if ch == '"' || ch == '\'' || ch == '`' {
            let q = ch;
            out.push(ch);
            i += 1;
            while i < n {
                if c[i] == '\\' {
                    // The JS slices two units even at the very end; `.min(n)` reproduces that bound.
                    let end = (i + 2).min(n);
                    out.extend(&c[i..end]);
                    i += 2;
                    continue;
                }
                out.push(c[i]);
                if c[i] == q {
                    i += 1;
                    break;
                }
                i += 1;
            }
            continue;
        }
        if ch == '/' && i + 1 < n && c[i + 1] == '/' {
            while i < n && c[i] != '\n' {
                i += 1; // to end of line; the \n is copied on the next pass
            }
            continue;
        }
        if ch == '/' && i + 1 < n && c[i + 1] == '*' {
            i += 2;
            while i < n && !(c[i] == '*' && i + 1 < n && c[i + 1] == '/') {
                if c[i] == '\n' {
                    out.push('\n');
                }
                i += 1;
            }
            i += 2;
            continue;
        }
        out.push(ch);
        i += 1;
    }
    out
}
